from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Ftm_type(EmssimCommand):
    def __init__(self, method="ftm_type", timeout=60, rpc_connection_name='localRPC'):
        super(Ftm_type, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Ftm_type, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Detected FTM type"):
                self._ret['ftm_type'] = data['ftm_type']
        elif ("status" in data):
            self._ret["status"] = data["status"]
